import pandas as pd

def clean(df):
    df = df.copy()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].str.replace(',', ''), errors='coerce')
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500) & (df['sex'].notna())]
    return df

def answer(df):
    grouped = df.groupby('sex')['body_mass_g'].mean()
    return {k: v for k, v in grouped.items() if not pd.isna(v)}
